--
-- Disparadores `pagos`
--
DELIMITER $$
CREATE TRIGGER `estatus` AFTER INSERT ON `pagos` FOR EACH ROW BEGIN 
     IF (SELECT SUM(monto) FROM pagos WHERE compra = New.compra) >= (SELECT total FROM compras WHERE id_compra = New.compra) 
     THEN 
        UPDATE compras SET estatus = 'Pagado' WHERE id_compra = New.compra;
     ELSE 
        UPDATE compras SET estatus = 'Sin pagar' WHERE id_compra = New.compra; 
     END IF; 
 END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `estatuselim` AFTER DELETE ON `pagos` FOR EACH ROW BEGIN 
     IF (SELECT SUM(monto) FROM pagos WHERE compra = old.compra) >= (SELECT total FROM compras WHERE id_compra = Old.compra) 
     THEN 
        UPDATE compras SET estatus = 'Pagado' WHERE id_compra = Old.compra;
     ELSE 
        UPDATE compras SET estatus = 'Sin pagar' WHERE id_compra = Old.compra; 
     END IF; 
 END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `estatusmod` AFTER UPDATE ON `pagos` FOR EACH ROW BEGIN 
     IF (SELECT SUM(monto) FROM pagos WHERE compra = New.compra) >= (SELECT total FROM compras WHERE id_compra = New.compra) 
     THEN 
        UPDATE compras SET estatus = 'Pagado' WHERE id_compra = New.compra;
     ELSE 
        UPDATE compras SET estatus = 'Sin pagar' WHERE id_compra = New.compra; 
     END IF; 
 END
$$
DELIMITER ;

